const samples=[{type:"Industrial",deal:"Lease",city:"Mississauga",area:"Central GTA",size:42000,title:"Modern Distribution Facility",rate:"Illustrative lease",icon:"▥"},{type:"Industrial",deal:"Sale",city:"Etobicoke",area:"Toronto",size:18500,title:"Industrial Ownership Opportunity",rate:"Illustrative sale",icon:"▥"},{type:"Office",deal:"Lease",city:"Toronto",area:"Central GTA",size:8500,title:"Professional Office Space",rate:"Illustrative lease",icon:"▤"},{type:"Retail",deal:"Lease",city:"Oakville",area:"Halton",size:3200,title:"Neighbourhood Retail Space",rate:"Illustrative lease",icon:"▣"},{type:"Land",deal:"Sale",city:"Brampton",area:"Peel",size:120000,title:"Employment Land Parcel",rate:"Illustrative sale",icon:"⌖"},{type:"Investment",deal:"Sale",city:"Vaughan",area:"York",size:27500,title:"Multi-Tenant Investment Property",rate:"Illustrative sale",icon:"◇"}];const featured=[samples[0],samples[4],samples[5]];function card(x){return '<article class="listing-card"><div class="property-art"><span aria-hidden="true">'+x.icon+'</span><small>FICTIONAL SAMPLE</small></div><div class="property-copy"><div class="demo-label">'+x.type.toUpperCase()+' · '+x.deal.toUpperCase()+'</div><h3>'+x.title+'</h3><p>'+x.city+' · '+x.area+'</p><div class="property-meta"><span>'+x.size.toLocaleString('en-CA')+' SF</span><span>'+x.rate+'</span></div></div></article>'}function render(){const city=document.getElementById('qcity').value.trim().toLowerCase();const type=document.getElementById('qtype').value;const deal=document.getElementById('qdeal').value;const range=document.getElementById('qsize').value;const parts=range?range.split('-').map(Number):null;const filtered=samples.filter(x=>(!city||(x.city+' '+x.area).toLowerCase().includes(city))&&(!type||x.type===type)&&(!deal||x.deal===deal)&&(!parts||(x.size>=parts[0]&&(!parts[1]||x.size<parts[1]))));document.getElementById('sample-results').innerHTML=filtered.length?filtered.map(card).join(''):'<p>No sample properties match these filters. Try clearing one or more filters.</p>';document.getElementById('listing-count').textContent=filtered.length+' sample results'}document.getElementById('featured-results').innerHTML=featured.map(card).join('');['qcity','qtype','qdeal','qsize'].forEach(id=>document.getElementById(id).addEventListener('input',render));document.getElementById('clear-filters').addEventListener('click',()=>{['qcity','qtype','qdeal','qsize'].forEach(id=>document.getElementById(id).value='');render()});render();
const query=new URLSearchParams(location.search);const filterMap={city:"qcity",type:"qtype",deal:"qdeal",size:"qsize"};Object.entries(filterMap).forEach(([key,id])=>{const el=document.getElementById(id);if(query.has(key)){const value=query.get(key);if(el.tagName!=="SELECT"||Array.from(el.options).some(o=>o.value===value))el.value=value;}});function syncBrief(){const q=new URLSearchParams();Object.entries(filterMap).forEach(([key,id])=>{const value=document.getElementById(id).value;if(value)q.set(key,value);});document.getElementById("search-brief").href="contact.html?"+q.toString();history.replaceState(null,"",location.pathname+(q.size?"?"+q:""));}Object.values(filterMap).forEach(id=>document.getElementById(id).addEventListener("input",syncBrief));document.getElementById("clear-filters").addEventListener("click",syncBrief);render();syncBrief();